import {catalog,standard,sources,relationGroups,types,inScope,hierarchy,standardConnections,conceptFlows,conceptPathwaysIndex,taskPathwaysIndex} from './store.mjs';
import {esc,url,heading,standardURL,pill,list,scopeSelect,empty,sourcesHTML,relationLiteratureHTML} from './ui.mjs';
export async function connectionsPage(p){
 const s=standard(p.get('code')||'6수02-03');if(!s)return empty('등록되지 않은 성취기준입니다.');
 const data=await standardConnections(s.code),groups=relationGroups(data.relations,s.code,p.get('scope')||'all',p.get('type')||'');
 const active=data.relations.find(r=>r.id===p.get('relation')&&[r.from,r.to].includes('standard:'+s.code));
 const group=active&&groups.find(g=>g.records.some(r=>r.id===active.id));
 return `<a class="button" href="${url('hierarchy',{q:s.code})}">← 이 기준의 위계 찾기</a>`+heading('CONNECTIONS','성취기준 사이의 연결','관계의 종류를 고르고 연결의 이유와 조건을 읽어보세요.')+
 `<div class="focus-standard"><div><span>${esc(s.code)} · ${esc(s.level)}</span><h2>${esc(s.title)}</h2><p>${esc(s.statement)}</p></div><a class="button" href="${standardURL(s.code)}">이 기준의 상세 읽기 ↗</a></div>`+
 `<div class="connection-toolbar"><form data-filter="connections">${scopeSelect(p.get('scope')||'all')}<input type="hidden" name="code" value="${esc(s.code)}"><button class="button">범위 적용</button></form><div class="tabs" aria-label="관계 유형">${[['','모든 관계'],...Object.entries(types).filter(([k])=>['meaning_connection','generalizes','requires_for_task','contrasts'].includes(k))].map(([key,label])=>`<a class="${(p.get('type')||'')===key?'active':''}" href="${url('connections',{code:s.code,scope:p.get('scope')||'',type:key})}">${label}</a>`).join('')}</div></div>`+
 `<div class="connections-layout"><section class="relation-groups"><div class="section-line"><h2>연결된 기준</h2><span>${groups.length}개 묶음</span></div>${['초등학교','중학교','고등학교'].map(level=>{const gs=groups.filter(g=>g.other.level===level);return gs.length?`<details class="relation-school" data-open="relations-${level}" open><summary>${level}<span>${gs.length}개</span></summary>${gs.slice(0,Number(p.get('limit'))||12).map(g=>`<a class="relation-choice ${group===g?'selected':''}" href="${url('connections',{...Object.fromEntries(p),code:s.code,relation:g.records[0].id})}" data-keep-scroll>${pill(types[g.type])}<small>${g.records.length}개 설명 · ${esc(g.other.code)}</small><h3>${esc(g.other.title)}</h3><p>${esc(g.records[0].scope)}</p><span class="text-link">연결 이유 읽기 →</span></a>`).join('')}${gs.length>(Number(p.get('limit'))||12)?`<a class="button" href="${url('connections',{...Object.fromEntries(p),limit:(Number(p.get('limit'))||12)+24})}" data-keep-scroll>이 학교급 연결 더 보기 ↓</a>`:''}</details>`:'';}).join('')||'<p class="empty">선택한 범위에 기록된 관계가 없습니다.</p>'}</section><aside class="relation-evidence" id="relation-evidence">${group?evidence(group,s,data):`<div class="evidence-placeholder"><span class="large-symbol">↔</span><h2>연결의 이유를 읽어보세요</h2><p>왼쪽에서 관계를 선택하면 연결의 범위, 추가 학습과 성립 조건이 여기에 표시됩니다.</p></div>`}</aside></div>`;
}
function evidence(group,s,data){const first=group.records[0],from=standard(first.from.slice(9)),to=standard(first.to.slice(9));return `<div class="evidence-heading">${pill(types[group.type])}<h2>${esc(from.title)}<span>${['generalizes','requires_for_task'].includes(group.type)?'↓':'↔'}</span>${esc(to.title)}</h2><a href="${standardURL(group.other.code)}">${esc(group.other.code)} 상세 읽기 ↗</a></div>${group.records.map(r=>`<article class="evidence-record"><p class="eyebrow">${esc(r.id)} · ${esc(r.status)}</p><h3>연결 범위</h3><p>${esc(r.scope)}</p><h3>왜 연결될까요?</h3><p>${esc(r.rationale)}</p>${r.additional_learning?.length?'<h3>새로 필요한 사고</h3>'+list(r.additional_learning):''}<h3>성립 조건</h3>${r.condition_scope_note?`<p>${esc(r.condition_scope_note)}</p>`:''}${list(r.conditions)}${r.prerequisite_group?`<h3>함께 필요한 조건 · ${esc(r.prerequisite_group.operator)}</h3>${list(r.prerequisite_group.members)}`:''}${r.intermediate_standards?.length?'<h3>함께 살펴볼 중간 기준</h3>'+r.intermediate_standards.map(c=>`<a class="button" href="${standardURL(c)}">${esc(c)} ↗</a>`).join(''):''}${r.diagnostic?'<h3>확인 질문</h3><p>'+esc(r.diagnostic)+'</p>':''}${r.expected_response?'<h3>기대하는 설명</h3><p>'+esc(r.expected_response)+'</p>':''}${r.alternative_route?'<h3>다른 설명 경로</h3><p>'+esc(r.alternative_route)+'</p>':''}<h3>해석의 범위</h3><p>${esc(r.limit)}</p><h3>출처와 실제 검토 범위</h3>${sourcesHTML(data.sources.filter(x=>(r.source_ids||[]).includes(x.id)))}${relationLiteratureHTML(r)}</article>`).join('')}<p class="notice">연결 분석은 연구 초안입니다. 의미 연결과 과제별 조건은 서로 다른 관계입니다.</p>`;}
export async function hierarchyPage(p,root,isCurrent=()=>true){
 if(p.get('mode')==='goals'&&p.get('target')){const {goalNetworkPage}=await import('./goal-network.mjs');const html=await goalNetworkPage(p);if(!isCurrent())return ()=>{};root.innerHTML=html;return ()=>{};}
 if(p.get('mode')==='tasks'&&p.get('target')){const {taskPathwayPage}=await import('./task-pathways.mjs');const html=await taskPathwayPage(p);if(!isCurrent())return ()=>{};root.innerHTML=html;return ()=>{};}
 if(p.get('concept')){const {conceptPathwayPage}=await import('./concept-pathways.mjs');const html=await conceptPathwayPage(p);if(!isCurrent())return ()=>{};root.innerHTML=html;const scroll=root.querySelector('.hp-scroll'),goal=root.querySelector('.hp-goal');if(scroll&&goal)scroll.scrollLeft+=goal.getBoundingClientRect().left-scroll.getBoundingClientRect().left-scroll.clientWidth/2+goal.getBoundingClientRect().width/2;return ()=>{};}
 const data=await hierarchy();
 if(!p.get('map')){const [flows,index,tasks]=await Promise.all([conceptFlows(),conceptPathwaysIndex(),taskPathwaysIndex()]);const {hierarchyHome}=await import('./pathways.mjs');if(!isCurrent())return ()=>{};root.innerHTML=hierarchyHome(p,data,flows,index,tasks);return ()=>{};}
 const map=data.hierarchy.maps.find(item=>item.id===p.get('map'));
 if(!map)throw Object.assign(new Error('등록되지 않은 시범 지도입니다. 수학 개념 목록에서 다시 선택해 주세요.'),{invalidSelection:true});
 const scope=p.get('scope')||'all';
 window.CurriculumScope={current:()=>({id:scope,title:{all:'초·중·고 전체',e:'초등학교',m:'중학교',h:'고등학교',em:'초등·중학교',mh:'중학교·고등학교'}[scope]||'전체'}),includes:s=>inScope(s,scope),visibleHierarchy:(map,route,byCode,id)=>{
  const full=window.CurriculumHierarchy.context(map,route,byCode,s=>inScope(s,id));if(p.get('external')==='1'||id==='all')return full;const nodes=full.nodes.filter(n=>!n.boundary),ids=new Set(nodes.map(n=>n.id)),claims=full.claims.filter(c=>ids.has(c.source)&&ids.has(c.target));return {...full,nodes,claims,boundaryCount:0,hiddenNodes:full.nodes.length-nodes.length,hiddenClaims:full.claims.length-claims.length};
 }};
 root.innerHTML=heading('PATHWAYS','개념의 위계와 학습 경로','과제와 풀이 경로에 따라 함께 필요한 사고를 살펴보세요.')+`<a class="button" href="${url('hierarchy',{scope})}">← 전체 개념에서 찾기</a><form class="hierarchy-filter" data-filter="hierarchy">${scopeSelect(scope)}<label><input type="checkbox" name="external" value="1" ${p.get('external')==='1'?'checked':''}>다른 학교급의 전체 조건 함께 보기</label>${['map','route','target','node','claim','compare','kind'].filter(k=>p.has(k)).map(k=>`<input type="hidden" name="${k}" value="${esc(p.get(k))}">`).join('')}<button class="button">범위 적용</button></form><div id="hierarchy-root"></div>`;
 return window.CurriculumHierarchy.init(root.querySelector('#hierarchy-root'),p,{...data,standards:catalog.standards});
}
export async function aboutPage(){const records=await sources();return heading('ABOUT THE CORPUS','자료와 분석 기준','공식 성취기준과 수학적 분석, 수업 설계의 근거를 확인합니다.')+`<div class="about-summary"><h2>2022 개정 수학과 교육과정</h2><p>제공된 교육부 고시 제2022-33호 별책8의 성취기준 435개와 고교 15과목을 다룹니다. 후속 일부개정 반영 여부는 별도 확인 대상입니다.</p><p>상세 분석과 연결은 연구 초안입니다. 원문 대조, 분석 검토와 학생 반응 검증은 각각 다른 상태로 표시합니다.</p><p>공통 문서 체계와 개별 보강을 반영한 상세 초안 ${catalog.meta.individualRevisionDrafts||0}개를 제공합니다. 자체 분석과 독립 검토, 학생 반응 검증을 구별합니다.</p><div class="stat-row"><div><strong>435</strong><span>성취기준</span></div><div><strong>${catalog.meta.elements}</strong><span>사고 요소</span></div><div><strong>${catalog.meta.reviewed}</strong><span>검토 완료</span></div><div><strong>${catalog.meta.studentValidated}</strong><span>학생 반응 검증</span></div></div><a class="button" href="curriculum.pdf" target="_blank" rel="noopener">교육과정 원문 열기 ↗</a><details class="further"><summary>원본 판본 식별 정보</summary><p class="hash">SHA256 ${esc(catalog.meta.sourceSha256)}</p></details></div><div class="sources-list">${sourcesHTML(records)}</div>`;}

